public final class AcmePayAdapter implements PaymentGateway {
    private final AcmePayChargeOperation acmePay;

    public AcmePayAdapter(AcmePayChargeOperation acmePay) {
        this.acmePay = Objects.requireNonNull(acmePay, "acmePay");
    }

    @Override public String charge(long amountCents, Currency currency) {
        return acmePay.createCharge(amountCents, currency.getCurrencyCode());
    }
}

